b_standard_deduction = observation(entity='Alice', entity_source='s55', predicate='allowed a deduction under section 63(c)', predicate_source='s55')
b_personal_exemptions = observation(entity='Alice', entity_source='s55', predicate='deductions of $4000 under section 151', predicate_source='s55')
b_gross_income = observation(entity='Alice', entity_source='s55', predicate='paid $33200', predicate_source='s55')
b_taxable_income = observation(entity='Alice', entity_source='s56', predicate='taxable income in 2017 is equal to $31200', predicate_source='s56')

@scope('s0')
def taxable_income_definition_scope():
    return True

@rule('s2', otherwise=False)
def taxable_income_definition():
    return (taxable_income_definition_scope and b_gross_income and (not b_standard_deduction) and (not b_personal_exemptions))

query = ('Entailment' if taxable_income_definition else 'Contradiction')
